import {useState, useMemo, useCallback} from 'react'
import {Flash, TextInput, UnderlineNav} from '@primer/react'
import {SearchIcon} from '@primer/octicons-react'
import type {RepositoryPolicy} from '../types/route'
import {AllowedLicensesTable} from './AllowedLicensesTable'
import {PackageExceptionsTable} from './PackageExceptionsTable'
import styles from '../routes/license-compliance.module.css'

type TabType = 'licenses' | 'exceptions'

interface RepositoryPolicySectionProps {
  repositoryPolicy: RepositoryPolicy
}

function filterByText<T>(items: T[], filter: string, getSearchField: (item: T) => string): T[] {
  if (!filter) return items
  const lowerFilter = filter.toLowerCase()
  return items.filter(item => getSearchField(item).toLowerCase().includes(lowerFilter))
}

export function RepositoryPolicySection({repositoryPolicy}: RepositoryPolicySectionProps) {
  const [activeTab, setActiveTab] = useState<TabType>('licenses')
  const [searchFilter, setSearchFilter] = useState('')
  const {allowedLicenses, packageExceptions, customRemediationGuidance, error} = repositoryPolicy

  const handleTabChange = useCallback((tab: TabType) => {
    setActiveTab(tab)
    setSearchFilter('')
  }, [])

  const filteredLicenses = useMemo(
    () => filterByText(allowedLicenses, searchFilter, license => license.spdxId),
    [allowedLicenses, searchFilter],
  )

  const filteredPackages = useMemo(
    () => filterByText(packageExceptions, searchFilter, pkg => pkg.name),
    [packageExceptions, searchFilter],
  )

  const searchPlaceholder = activeTab === 'licenses' ? 'Search licenses' : 'Search packages'

  return (
    <section data-testid="repository-policy-section">
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h2 className={styles.sectionTitle}>Repository Policy</h2>

      {error && (
        <Flash variant="danger" className={styles.flashMessage} data-testid="policy-error-flash">
          Failed to load repository policy: {error}
        </Flash>
      )}

      {customRemediationGuidance && (
        <div className={styles.helperText}>
          <p>
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            <strong>Custom Remediation Guidance:</strong> {customRemediationGuidance}
          </p>
        </div>
      )}

      <UnderlineNav aria-label="Repository policy navigation" className={styles.policyNav}>
        <UnderlineNav.Item
          aria-current={activeTab === 'licenses' ? 'page' : undefined}
          onSelect={() => handleTabChange('licenses')}
          counter={allowedLicenses.length}
          data-testid="licenses-tab"
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        >
          Allowed Licenses
        </UnderlineNav.Item>
        <UnderlineNav.Item
          aria-current={activeTab === 'exceptions' ? 'page' : undefined}
          onSelect={() => handleTabChange('exceptions')}
          counter={packageExceptions.length}
          data-testid="exceptions-tab"
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        >
          Package Exceptions
        </UnderlineNav.Item>
      </UnderlineNav>

      <div className={styles.searchContainer}>
        <TextInput
          leadingVisual={SearchIcon}
          placeholder={searchPlaceholder}
          value={searchFilter}
          onChange={e => setSearchFilter(e.target.value)}
          aria-label={searchPlaceholder}
          data-testid="policy-search-input"
        />
      </div>

      {activeTab === 'licenses' ? (
        <AllowedLicensesTable licenses={filteredLicenses} />
      ) : (
        <PackageExceptionsTable packages={filteredPackages} />
      )}
    </section>
  )
}
