import {Button, Flash, FormControl, Stack, TextInput} from '@primer/react'
import type {CheckJobResponse} from '../types/check-job'
import type {StafftoolsAlert} from '../types/alerts'
import {CheckJobDetailsTable} from './CheckJobDetailsTable'
import {AlertsTable} from './AlertsTable'
import styles from '../routes/license-compliance.module.css'

interface PRLicenseCheckSectionProps {
  prNumber: string
  onPrNumberChange: (value: string) => void
  checkJob: CheckJobResponse | null
  openAlerts: StafftoolsAlert[]
  closedAlerts: StafftoolsAlert[]
  error: string | null
  alertsError: string | null
  loading: boolean
  resetMessage: string | null
  hasSearched: boolean
  onFetchLicenseData: () => void
  onResetCheckJob: () => void
}

export function PRLicenseCheckSection({
  prNumber,
  onPrNumberChange,
  checkJob,
  openAlerts,
  closedAlerts,
  error,
  alertsError,
  loading,
  resetMessage,
  hasSearched,
  onFetchLicenseData,
  onResetCheckJob,
}: PRLicenseCheckSectionProps) {
  const canReset = checkJob && ['pass', 'fail', 'error', 'waiting'].includes(checkJob.status)
  const noAlerts = hasSearched && !alertsError && openAlerts.length === 0 && closedAlerts.length === 0
  const noCheckJob = hasSearched && !checkJob && !error

  return (
    <section>
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <h2 className={styles.sectionTitle}>PR License Check Data</h2>
      <p className={styles.helperText}>
        Retrieves check job status and license compliance alerts for the specified pull request.
      </p>

      <Stack direction="horizontal" gap="normal" align="end" className={styles.formRow}>
        <FormControl>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <FormControl.Label>Pull Request Number</FormControl.Label>
          <TextInput
            type="number"
            value={prNumber}
            onChange={e => onPrNumberChange(e.target.value)}
            placeholder="e.g. 123"
            className={styles.inputWidth}
            data-testid="pr-number-input"
          />
        </FormControl>
        <Button
          type="button"
          onClick={onFetchLicenseData}
          disabled={loading}
          variant="primary"
          data-testid="get-license-data-button"
        >
          {loading ? 'Loading...' : 'Get License Check Details'}
        </Button>
        {canReset && (
          <Button
            type="button"
            onClick={onResetCheckJob}
            disabled={loading}
            variant="danger"
            data-testid="reset-check-job-button"
            /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
          >
            Reset Check Job
          </Button>
        )}
      </Stack>

      {canReset && (
        <p className={styles.helperText}>
          Resetting the check job will re-run the license compliance check and recalculate alerts.
        </p>
      )}

      {error && (
        <Flash variant="danger" className={styles.flashMessage} data-testid="error-flash">
          {error}
        </Flash>
      )}

      {alertsError && (
        <Flash variant="danger" className={styles.flashMessage} data-testid="alerts-error-flash">
          {alertsError}
        </Flash>
      )}

      {resetMessage && (
        <Flash variant="success" className={styles.flashMessage} data-testid="success-flash">
          {resetMessage}
        </Flash>
      )}

      {noCheckJob && (
        <p className={styles.noAlerts} data-testid="no-check-job-message">
          No check job found for this PR. Check jobs are deleted after 30 days.
        </p>
      )}

      {checkJob && <CheckJobDetailsTable checkJob={checkJob} />}

      {noAlerts && (
        <p className={styles.noAlerts} data-testid="no-alerts-message">
          No license compliance alerts for this PR.
        </p>
      )}

      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      {openAlerts.length > 0 && <AlertsTable alerts={openAlerts} title="Open Alerts" tableId="open-alerts" />}

      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      {closedAlerts.length > 0 && <AlertsTable alerts={closedAlerts} title="Closed Alerts" tableId="closed-alerts" />}
    </section>
  )
}
