import {useMemo} from 'react'
import {DataTable, Table} from '@primer/react/experimental'
import type {PackageException} from '../types/route'
import {DEFAULT_PAGE_SIZE} from '../types/constants'
import {usePaginatedData} from '../hooks/use-paginated-data'
import styles from '../routes/license-compliance.module.css'

interface PackageExceptionsTableProps {
  packages: PackageException[]
  pageSize?: number
}

type PackageWithId = PackageException & {id: string}

export function PackageExceptionsTable({packages, pageSize = DEFAULT_PAGE_SIZE}: PackageExceptionsTableProps) {
  const tableId = 'package-exceptions-table'

  const packagesWithId = useMemo<PackageWithId[]>(
    () => packages.map(pkg => ({...pkg, id: `${pkg.packageManager}-${pkg.name}`})),
    [packages],
  )

  const {paginatedData, totalCount, showPagination, onPageChange} = usePaginatedData(packagesWithId, {pageSize})

  if (packages.length === 0) {
    return <p className={styles.noAlerts}>No package exceptions configured.</p>
  }

  return (
    <Table.Container data-testid={tableId}>
      <DataTable
        aria-labelledby={tableId}
        data={paginatedData}
        columns={[
          {
            header: 'Name',
            field: 'name',
            renderCell: row => row.name || 'N/A',
          },
          {
            header: 'Package Manager',
            field: 'packageManager',
            width: '140px',
            renderCell: row => row.packageManager || 'N/A',
          },
          {
            header: 'Action',
            field: 'action',
            width: '100px',
            renderCell: row => row.action || 'N/A',
          },
          {
            header: 'Level',
            field: 'level',
            width: '120px',
            renderCell: row => row.level || 'N/A',
          },
          {
            header: 'Reason',
            field: 'reason',
            renderCell: row => row.reason || 'N/A',
          },
          {
            header: 'Extra Allowed SPDX IDs',
            field: 'extraAllowedSpdxIds',
            renderCell: row => (row.extraAllowedSpdxIds.length > 0 ? row.extraAllowedSpdxIds.join(', ') : 'None'),
          },
          {
            header: 'Added At',
            field: 'addedAt',
            width: '180px',
            renderCell: row => row.addedAt || 'N/A',
          },
        ]}
      />
      {showPagination && (
        <Table.Pagination
          aria-label="Package exceptions pagination"
          pageSize={pageSize}
          totalCount={totalCount}
          onChange={pageInfo => onPageChange(pageInfo.pageIndex)}
        />
      )}
    </Table.Container>
  )
}
