import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {licenseComplianceRoute} from './license-compliance-route'
import {LicenseCompliancePage} from '../components/LicenseCompliancePage'

export function LicenseCompliance() {
  const payload = useRouteQuery(licenseComplianceRoute, 'mainQuery')

  return (
    <LicenseCompliancePage
      licenseComplianceOn={payload.data.licenseComplianceOn}
      repositoryNameWithOwner={payload.data.repositoryNameWithOwner}
      repositoryPolicy={payload.data.repositoryPolicy}
    />
  )
}
