import {DataTable, Table} from '@primer/react/experimental'
import type {StafftoolsAlert} from '../types/alerts'
import styles from '../routes/license-compliance.module.css'

interface AlertsTableProps {
  alerts: StafftoolsAlert[]
  title: string
  tableId: string
}

export function AlertsTable({alerts, title, tableId}: AlertsTableProps) {
  return (
    <Table.Container data-testid={tableId} className={styles.alertsTable}>
      <Table.Title as="h3" id={tableId}>
        {title}
      </Table.Title>
      <DataTable
        aria-labelledby={tableId}
        data={alerts}
        columns={[
          {
            header: 'Status',
            field: 'status',
            width: '120px',
          },
          {
            header: 'Resolution',
            field: 'resolution',
            width: '140px',
          },
          {
            header: 'Package',
            field: 'package_name',
            renderCell: row => `${row.package_name}@${row.package_version}`,
          },
          {
            header: 'Ecosystem',
            field: 'package_ecosystem',
            width: '100px',
          },
          {
            header: 'SPDX License Expression',
            field: 'license',
          },
          {
            header: 'Manifest',
            field: 'manifest_name',
          },
          {
            header: 'Created',
            field: 'created_at',
            width: '180px',
            renderCell: row => row.created_at || 'N/A',
          },
        ]}
      />
    </Table.Container>
  )
}
